import React, { useCallback } from 'react';

import type { YearMonth } from 'utils/timePeriod/timePeriodAvailability';
import {
  getClosedMonthIndex,
  isMonthAvailable,
  MONTH_NAMES_SHORT,
  QUARTER_MONTH_RANGES,
  TimePeriodType,
  toYearMonth,
} from 'utils/timePeriod/timePeriodAvailability';

import type { MonthPeriodType } from '../../constants';
import { useTimePeriodSliderPreview } from '../../hooks/useTimePeriodSliderPreview';
import {
  MonthLabelBtn,
  MonthLabelsRow,
  SliderAreaContainer,
} from '../../TimePeriodSelector.styles';
import { computeSliderPositions, getMonthIndexFromEnd } from '../../utils';
import { QuarterBrackets } from '../QuarterBrackets';
import { TimePeriodSliderTrack } from '../TimePeriodSliderTrack';

interface MonthSliderProps {
  type: MonthPeriodType;
  cutoffDate: string;
  selectedEnd: YearMonth | null;
  onEndChange: (end: YearMonth) => void;
}

export function TimePeriodMonthSlider({
  type,
  cutoffDate,
  selectedEnd,
  onEndChange,
}: Readonly<MonthSliderProps>) {
  const cutoffYear = new Date(cutoffDate).getFullYear();
  const closedMonthIndex = getClosedMonthIndex(cutoffDate);

  const selectedMonthIndex = selectedEnd
    ? getMonthIndexFromEnd(selectedEnd)
    : closedMonthIndex;

  const positions = computeSliderPositions(type, selectedEnd, closedMonthIndex);

  const clampMonthIndex = useCallback(
    (value: number) =>
      Math.max(0, Math.min(closedMonthIndex, Math.round(value))),
    [closedMonthIndex],
  );

  const {
    isDragging,
    previewEnd: previewMonthEnd,
    previewIndex: previewMonthIndex,
    handleDraggingChange,
    handleValueChange,
    handleValueCommit,
  } = useTimePeriodSliderPreview<YearMonth>({
    mapIndexToEnd: (idx) => {
      const clamped = clampMonthIndex(idx);
      return toYearMonth(clamped, cutoffYear);
    },
    onCommit: (end) => onEndChange(end),
  });

  const handleMonthValueChange = useCallback(
    (values: number[]) => {
      handleValueChange([clampMonthIndex(values[0] ?? 0)]);
    },
    [clampMonthIndex, handleValueChange],
  );

  const handleMonthValueCommit = useCallback(
    (values: number[]) => {
      handleValueCommit([clampMonthIndex(values[0] ?? 0)]);
    },
    [clampMonthIndex, handleValueCommit],
  );

  const previewPositions =
    isDragging && previewMonthEnd !== null
      ? computeSliderPositions(type, previewMonthEnd, closedMonthIndex)
      : null;

  return (
    <SliderAreaContainer data-testid="time-period-month-slider">
      <TimePeriodSliderTrack
        positions={positions}
        preview={isDragging ? previewPositions : null}
        isDragging={isDragging}
        cursor="pointer"
        sliderProps={{
          type: 'slider',
          min: 0,
          max: 11,
          maxInput: closedMonthIndex,
          step: 1,
          value: [
            isDragging
              ? (previewMonthIndex ?? selectedMonthIndex)
              : selectedMonthIndex,
          ],
          callback: handleMonthValueChange,
          onValueCommit: handleMonthValueCommit,
          onDraggingChange: handleDraggingChange,
          thumbAriaLabel: `Select ${type} end month`,
        }}
      />

      <MonthLabelsRow>
        {MONTH_NAMES_SHORT.map((month, index) => {
          const available = isMonthAvailable(index, cutoffDate);
          const isSelected = index === selectedMonthIndex;

          return (
            <MonthLabelBtn
              key={month}
              data-testid={`month-${month}`}
              type="button"
              disabled={!available}
              aria-pressed={isSelected}
              aria-label={`Select ${month}`}
              onClick={() => {
                if (available) {
                  onEndChange(toYearMonth(index, cutoffYear));
                }
              }}
            >
              {month}
            </MonthLabelBtn>
          );
        })}
      </MonthLabelsRow>

      <QuarterBrackets
        getState={(quarter) => {
          const { startMonthIndex, endMonthIndex: endMonth } =
            QUARTER_MONTH_RANGES[quarter];
          const isDisabled = endMonth > closedMonthIndex;
          const canClick =
            !isDisabled &&
            (type === TimePeriodType.R3M || type === TimePeriodType.YTD);
          const selectedStartMonthIndex = selectedMonthIndex - 2;
          const isActive =
            type === TimePeriodType.R3M &&
            selectedStartMonthIndex === startMonthIndex &&
            selectedMonthIndex === endMonth;

          return {
            active: isActive,
            disabled: !canClick,
            muted: isDisabled,
            ariaLabel: `Set ${type} through ${MONTH_NAMES_SHORT[endMonth]}`,
          };
        }}
        onSelect={(quarter) => {
          const { endMonthIndex } = QUARTER_MONTH_RANGES[quarter];
          onEndChange(toYearMonth(endMonthIndex, cutoffYear));
        }}
      />
    </SliderAreaContainer>
  );
}
